import { act, render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import type * as ReactRouterDom from "react-router-dom";
import { App } from "./App";
import { initInspectorStore, inspectorStore } from "./store";

let capturedOnInspectModeChange: ((inspect: boolean) => void) | undefined;
let mockSearchParamsGet: (key: string) => string | null = () => null;

vi.mock("./hooks/useBotConnection", () => ({
  useBotConnection: vi.fn(),
}));

vi.mock("./hooks/useTrackerConnection", () => ({
  useTrackerConnection: vi.fn(),
}));

vi.mock("./hooks/useConversationData", () => ({
  useConversationData: vi.fn(),
}));

vi.mock("./try-assistant/TryAssistant", () => ({
  TryAssistant: (props: { onInspectModeChange?: (inspect: boolean) => void }) => {
    capturedOnInspectModeChange = props.onInspectModeChange;
    return <div data-testid="try-assistant" />;
  },
}));

vi.mock("./components/StandaloneHeader", () => ({
  StandaloneHeader: () => <div data-testid="standalone-header" />,
}));

vi.mock("./assets/images", () => ({
  Background: "mock-background.png",
}));

vi.mock("react-router-dom", async (importOriginal) => {
  const actual = await importOriginal<typeof ReactRouterDom>();
  return {
    ...actual,
    useSearchParams: () => [{ get: (key: string) => mockSearchParamsGet(key) }],
  };
});

vi.mock("./theme", async () => {
  const { defaultSystem } = await import("@chakra-ui/react");
  return { system: defaultSystem };
});

vi.mock("uuid", () => ({
  v4: () => "generated-uuid",
}));

describe("App (standalone)", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    capturedOnInspectModeChange = undefined;
    mockSearchParamsGet = () => null;
    initInspectorStore();
  });

  it("renders StandaloneHeader", () => {
    render(<App />);
    expect(screen.getByTestId("standalone-header")).toBeInTheDocument();
  });

  it("renders TryAssistant", () => {
    render(<App />);
    expect(screen.getByTestId("try-assistant")).toBeInTheDocument();
  });

  it("initializes store with isEmbedded=false", () => {
    render(<App />);
    expect(inspectorStore.state.isEmbedded).toBe(false);
  });

  describe("projectUrl", () => {
    it("uses http://localhost:5005 when running in dev mode", () => {
      render(<App />);
      expect(inspectorStore.state.projectUrl).toBe("http://localhost:5005");
    });

    it("uses globalThis.location.origin when running in production mode", () => {
      const env = import.meta.env as Record<string, unknown>;
      const original = env.DEV;
      env.DEV = false;

      try {
        render(<App />);
        expect(inspectorStore.state.projectUrl).toBe(globalThis.location.origin);
      } finally {
        env.DEV = original;
      }
    });
  });

  describe("authToken", () => {
    it("initializes store with authToken from URL search params", () => {
      mockSearchParamsGet = (key) => (key === "token" ? "my-secret-token" : null);

      render(<App />);

      expect(inspectorStore.state.authToken).toBe("my-secret-token");
    });

    it("leaves authToken undefined when token is not in URL", () => {
      render(<App />);

      expect(inspectorStore.state.authToken).toBeUndefined();
    });
  });

  describe("inspect mode container width", () => {
    it("passes an onInspectModeChange callback to TryAssistant", () => {
      render(<App />);
      expect(capturedOnInspectModeChange).toBeTypeOf("function");
    });

    it("re-renders without errors when inspect mode is enabled", () => {
      render(<App />);
      act(() => capturedOnInspectModeChange!(true));
      expect(screen.getByTestId("try-assistant")).toBeInTheDocument();
    });

    it("re-renders without errors when inspect mode is disabled after being enabled", () => {
      render(<App />);
      act(() => capturedOnInspectModeChange!(true));
      act(() => capturedOnInspectModeChange!(false));
      expect(screen.getByTestId("try-assistant")).toBeInTheDocument();
    });
  });
});
